client_script:
// A group file is for the group's members only: the uploader offers no public file, web link or file browser.
var file_field = frappe.web_form.fields_dict.attached_file;
if (file_field) {
	file_field.df.options = {
		make_attachments_public: 0,
		allow_toggle_private: false,
		allow_web_link: false,
		allow_google_drive: false,
		disable_file_browser: true,
	};
}

// A saved file shows an Open button in place of the bare file path.
// Frappe draws the read-only value after this script runs, so the button replaces how it draws.
if (file_field && frappe.web_form.doc.name) {
	file_field.set_input = function (value) {
		if (!value) return;
		var $open = $('<a class="btn btn-primary btn-sm" target="_blank" rel="noopener"></a>')
			.attr("href", value)
			.text(__("Open {0}", [value.split("/").pop()]));
		this.$wrapper.empty().append($open);
	};
}
